
import { defineComponent, PropType } from 'vue';
import {
  AjaxHelper,
  ContentBlock,
  ContentTable,
  Matomo,
  NotificationType,
  NotificationsStore,
} from 'CoreHome';
import { Client } from '../types';

const notificationId = 'oauth2clientlist';

export default defineComponent({
  name: 'Oauth2ClientList',
  props: {
    clients: {
      type: Array as PropType<Client[]>,
      required: true,
    },
  },
  emits: ['create', 'edit', 'deleted', 'updated'],
  components: {
    ContentBlock,
  },
  directives: {
    ContentTable,
  },
  data() {
    return {
      confirmDeleteLabel: '',
      confirmToggleLabel: '',
      typeOptions: {
        confidential: this.translate('OAuth2_AdminConfidential'),
        public: this.translate('OAuth2_AdminPublic'),
      } as Record<string, string>,
    };
  },
  methods: {
    showNotification(message: string, context: NotificationType['context'],
      type: null|NotificationType['type'] = null) {
      const instanceId = NotificationsStore.show({
        message,
        context,
        id: notificationId,
        type: type !== null ? type : 'toast',
      });

      setTimeout(() => {
        NotificationsStore.scrollToNotification(instanceId);
      }, 200);
    },
    removeNotifications() {
      NotificationsStore.remove(notificationId);
      NotificationsStore.remove('ajaxHelper');
    },
    toggleClientStatus(client: Client) {
      this.confirmToggleLabel = client.active
        ? this.translate('OAuth2_AdminPauseConfirm', client.name || client.client_id)
        : this.translate('OAuth2_AdminResumeConfirm', client.name || client.client_id);

      Matomo.helper.modalConfirm(this.$refs.confirmToggleClient as HTMLElement, {
        yes: () => {
          AjaxHelper.fetch({
            method: 'OAuth2.setClientActive',
            clientId: client.client_id,
            active: client.active ? '0' : '1',
          }).then((response) => {
            if (response?.client) {
              this.removeNotifications();
              this.showNotification(
                response.client.active
                  ? this.translate('OAuth2_AdminResumed', response.client.name || response.client.client_id)
                  : this.translate('OAuth2_AdminPaused', response.client.name || response.client.client_id),
                'success',
              );
              this.$emit('updated', response.client);
            }
          });
        },
      });
    },
    deleteClient(client: Client) {
      this.confirmDeleteLabel = this.translate('OAuth2_AdminDeleteConfirm', client.name || client.client_id);

      Matomo.helper.modalConfirm(this.$refs.confirmDeleteClient as HTMLElement, {
        yes: () => {
          AjaxHelper.fetch({
            method: 'OAuth2.deleteClient',
            clientId: client.client_id,
          }).then((response) => {
            if (response?.deleted) {
              this.removeNotifications();
              this.showNotification(this.translate('OAuth2_AdminDeleted', client.client_id), 'success');
              this.$emit('deleted', client.client_id);
            }
          });
        },
      });
    },
  },
});
